  // Navbar.init ตรวจ login ให้เอง (redirect ไป index.html ถ้ายังไม่ login)
  // และ render topbar + popup โปรไฟล์ให้เสร็จ คืนค่า user object กลับมา
  const user = Navbar.init({ activePage: "home" });
  if (!user) return; // ถูก redirect ไปแล้ว

  // ดึงข้อมูลห้อง (ถ้ามีจริงจาก API ใช้ข้อมูลจริง ถ้าไม่มีใช้ข้อมูลตัวอย่าง)
  fetch("http://localhost:5001/api/rooms")
    .then(function (response) {
      return response.json();
    })
    .then(function (data) {
      const bookings = data.rooms || [];
      const floorSections =
        bookings.length > 0 ? groupRoomsByFloor(bookings) : MOCK_ROOMS_BY_FLOOR;
      renderFloorSections(floorSections);
    })
    .catch(function (error) {
      console.log(error);
      renderFloorSections(MOCK_ROOMS_BY_FLOOR);
    });

});
